('d88719f4-85d2-4212-93d7-d00d0980e891',null,false,null,null,null,null,null,null,null,null,null,'in_onderzoek','Verrijking vermogensfondsen batch 1, 16-10-2026 (Claude): niet gevonden; mogelijk afkorting of tikfout')
), u as (
update public.funders f set
 website = case when v.force then v.website else coalesce(nullif(f.website,''), v.website) end,
 missie = coalesce(nullif(f.missie,''), v.missie),
 plaats = coalesce(nullif(f.plaats,''), v.plaats),
 provincie = coalesce(nullif(f.provincie,''), v.provincie),
 land = coalesce(nullif(f.land,''), v.land),
 aanvraagcriteria = coalesce(nullif(f.aanvraagcriteria,''), v.criteria),
 bijdrage_min = coalesce(f.bijdrage_min, v.bmin::numeric),
 bijdrage_max = coalesce(f.bijdrage_max, v.bmax::numeric),
 bijdrage_toelichting = coalesce(nullif(f.bijdrage_toelichting,''), v.btoel),
 vergaderfrequentie = coalesce(nullif(f.vergaderfrequentie,''), v.vergfreq),
 enrichment_status = v.es::enrichment_status_type,
 research_source = v.rs,
 last_researched_at = now()
from v where f.id = v.id::uuid returning 1)
select count(*) as funders_bijgewerkt from u;
